    //  2. FMT_F EXTENDED "-0" GUARD
    // ═══════════════════════════════════════════════════════════════════════

    #[test]
    fn fmt_f_negative_zero_literal() {
        assert_eq!(fmt_f(-0.0), "0", "-0.0 must produce '0'");
    }

    #[test]
    fn fmt_f_negative_zero_from_tiny_negative() {
        // -0.0004 at precision 3: format!("{:.3}", -0.0004) = "-0.000"
        // trimmed = "-0.000" -> trim '0' -> "-0." -> trim '.' -> "-0"
        // The extended guard catches "-0" and returns "0".
        assert_eq!(
            fmt_f(-0.0004),
            "0",
            "FIXED: -0.0004 must produce '0' after extended -0 guard, not '-0'"
        );
    }

    #[test]
    fn fmt_f_negative_zero_from_very_small_negative() {
        // -0.00049 at precision 3: rounds to "-0.000" -> trimmed to "-0" -> "0"
        assert_eq!(fmt_f(-0.00049), "0");
    }

    #[test]
    fn fmt_f_negative_zero_from_minus_epsilon() {
        // A value just barely below zero
        assert_eq!(fmt_f(-1e-10), "0",
            "very small negative should be '0' after precision trimming");
    }

    #[test]
    fn fmt_f_small_negative_that_survives_trimming() {
        // -0.001 at precision 3: format!("{:.3}", -0.001) = "-0.001"
        // trimmed = "-0.001" -> no trailing zeros to trim -> "-0.001"
        // This is NOT "-0", so it should survive.
        assert_eq!(fmt_f(-0.001), "-0.001",
            "-0.001 should NOT be collapsed to 0 — it has a non-zero digit");
    }

    #[test]
    fn fmt_f_positive_zero() {
        assert_eq!(fmt_f(0.0), "0");
    }

    #[test]
    fn fmt_f_nan_returns_zero() {
        assert_eq!(fmt_f(f64::NAN), "0", "NaN must produce '0' not 'NaN'");
    }

    #[test]
    fn fmt_f_infinity_returns_zero() {
        assert_eq!(fmt_f(f64::INFINITY), "0", "Infinity must produce '0'");
    }

    #[test]
    fn fmt_f_neg_infinity_returns_zero() {
        assert_eq!(fmt_f(f64::NEG_INFINITY), "0");
    }

    #[test]
    fn fmt_f_normal_negative() {
        assert_eq!(fmt_f(-42.5), "-42.5");
    }

    #[test]
    fn fmt_f_large_positive() {
        // f64::MAX is finite but huge. Make sure it doesn't produce NaN/Inf.
        let s = fmt_f(f64::MAX);
        assert!(!s.contains("NaN"), "MAX f64 must not contain NaN");
        assert!(!s.contains("inf"), "MAX f64 must not contain inf");
        assert!(!s.is_empty());
    }

    #[test]
    fn fmt_f_subnormal_positive() {
        // 5e-324 rounds to 0.000 at precision 3, trimmed to "0"
        assert_eq!(fmt_f(5e-324), "0");
    }

    #[test]
    fn fmt_f_negative_0_00001_trimmed_to_zero() {
        // -0.00001 at precision 3: format!("{:.3}", -0.00001) = "-0.000"
        // trimmed = "-0" -> guard catches it -> "0"
        assert_eq!(fmt_f(-0.00001), "0");
    }

    // ═══════════════════════════════════════════════════════════════════════
    //  3. SPAN FILL_OPACITY (ANNOTATION.RS)
    // ═══════════════════════════════════════════════════════════════════════

    #[test]
    fn span_opacity_stored_as_fill_opacity() {
        // The span annotation now stores caller-supplied opacity as fill_opacity,
        // not opacity. Verify the contract: fill_opacity carries the user value,
        // opacity is always 1.0.
        let caller_opacity = 0.2_f64;
        let fill_opacity = caller_opacity;
        let opacity = 1.0_f64;
        assert!((fill_opacity - 0.2).abs() < f64::EPSILON,
            "span fill_opacity must carry caller opacity");
        assert!((opacity - 1.0).abs() < f64::EPSILON,
            "span opacity field must be 1.0");
    }

    #[test]
    fn span_opacity_zero_makes_invisible() {
        // opacity=0 stored as fill_opacity=0 -> SVG emits fill-opacity="0"
        // which makes the span rectangle invisible.
        let fill_opacity = 0.0_f64;
        assert!(fill_opacity < 1.0, "fill_opacity=0 should trigger SVG emission");
        // In push_fill_stroke: `if s.fill_opacity < 1.0 { emit fill-opacity }`
        // fill-opacity="0" makes the rect invisible.
    }

    #[test]
    fn span_opacity_one_omits_attribute() {
        // opacity=1.0 stored as fill_opacity=1.0 -> SVG omits fill-opacity attribute
        let fill_opacity = 1.0_f64;
        let emits_fill_opacity = fill_opacity < 1.0;
        assert!(!emits_fill_opacity,
            "fill_opacity=1.0 should not emit fill-opacity attribute");
    }

    #[test]
    fn span_opacity_greater_than_one_not_clamped() {
        // There's no clamping in the span code — opacity > 1.0 is passed
        // through to fill_opacity. SVG ignores values > 1 (treats as 1), but
        // the code doesn't clamp it. This is a minor gap.
        let caller_opacity = 2.0_f64;
        let fill_opacity = caller_opacity;
        assert!((fill_opacity - 2.0).abs() < f64::EPSILON,
            "span code does NOT clamp opacity > 1.0 — relies on SVG renderer");
    }

    // ═══════════════════════════════════════════════════════════════════════
    //  4. SPAN NaN GUARD (ANNOTATION.RS)
    // ═══════════════════════════════════════════════════════════════════════

    #[test]
    fn span_nan_x_start_skips_emission() {
        // The NaN guard in emit_span checks is_finite() on both resolved coords.
        // NaN is not finite, so the span is skipped entirely.
        let x_start = f64::NAN;
        let x_end = 200.0_f64;
        let should_emit = x_start.is_finite() && x_end.is_finite();
        assert!(!should_emit, "NaN x_start must skip span emission");
    }

    #[test]
    fn span_nan_x_end_skips_emission() {
        let x_start = 100.0_f64;
        let x_end = f64::NAN;
        let should_emit = x_start.is_finite() && x_end.is_finite();
        assert!(!should_emit, "NaN x_end must skip span emission");
    }

    #[test]
    fn span_infinity_x_start_skips_emission() {
        let x_start = f64::INFINITY;
        let x_end = 200.0_f64;
        let should_emit = x_start.is_finite() && x_end.is_finite();
        assert!(!should_emit, "Infinity x_start must skip span emission");
    }

    #[test]
    fn span_neg_infinity_y_end_skips_emission() {
        let y_start = 100.0_f64;
        let y_end = f64::NEG_INFINITY;
        let should_emit = y_start.is_finite() && y_end.is_finite();
        assert!(!should_emit, "NEG_INFINITY y_end must skip span emission");
    }

    #[test]
    fn span_both_finite_emits() {
        let x_start = 100.0_f64;
        let x_end = 200.0_f64;
        let should_emit = x_start.is_finite() && x_end.is_finite();
        assert!(should_emit, "both finite coords must emit the span");
    }

