    // ═══════════════════════════════════════════════════════════════════════
    //  6. EPSILON ARROW HEAD CLAMPED (ANNOTATION.RS)
    // ═══════════════════════════════════════════════════════════════════════

    #[test]
    fn arrow_head_clamped_to_shaft_length() {
        // Short shaft (0.001px) with large head_size (8.0px):
        // head_size is clamped to shaft_length so arrowhead doesn't overshoot.
        let shaft_len = 0.001_f64;
        let head_size = 8.0_f64;
        let clamped = arrow_head_size_clamped(head_size, shaft_len);
        assert!((clamped - 0.001).abs() < 1e-10,
            "FIXED: arrowhead must be clamped to shaft length; got {clamped}");
    }

    #[test]
    fn arrow_head_not_clamped_when_smaller() {
        // Normal case: head_size < shaft_length — no clamping.
        let shaft_len = 100.0_f64;
        let head_size = 8.0_f64;
        let clamped = arrow_head_size_clamped(head_size, shaft_len);
        assert!((clamped - 8.0).abs() < 1e-10, "no clamping needed; got {clamped}");
    }

    #[test]
    fn arrow_head_clamped_when_equal() {
        let shaft_len = 8.0_f64;
        let head_size = 8.0_f64;
        let clamped = arrow_head_size_clamped(head_size, shaft_len);
        assert!((clamped - 8.0).abs() < 1e-10);
    }

    #[test]
    fn arrow_head_zero_shaft_length() {
        // Zero-length shaft: head_size.min(0.0) = 0.0
        let clamped = arrow_head_size_clamped(8.0, 0.0);
        assert_eq!(clamped, 0.0);
    }

    // ═══════════════════════════════════════════════════════════════════════
    //  7. NaN OPACITY GUARD IN EMIT_TEXT (SVG_WALK.RS)
    // ═══════════════════════════════════════════════════════════════════════

    #[test]
    fn emit_text_nan_opacity_defaults_to_opaque() {
        // FIXED: NaN opacity now defaults to 1.0 (fully opaque) instead of
        // producing alpha=0 (invisible text).
        let alpha = emit_text_compute_alpha(0xFF, f64::NAN);
        assert_eq!(alpha, 0xFF,
            "FIXED: NaN opacity must produce alpha=255 (opaque), not 0 (invisible)");
    }

    #[test]
    fn emit_text_normal_opacity() {
        let alpha = emit_text_compute_alpha(0xFF, 0.5);
        // effective_alpha = (255/255) * 0.5 = 0.5, alpha_byte = 128
        assert_eq!(alpha, 128);
    }

    #[test]
    fn emit_text_zero_opacity() {
        let alpha = emit_text_compute_alpha(0xFF, 0.0);
        assert_eq!(alpha, 0, "zero opacity must produce alpha=0");
    }

    #[test]
    fn emit_text_opacity_greater_than_one() {
        // opacity > 1.0: clamp to 1.0 via .clamp(0.0, 1.0)
        let alpha = emit_text_compute_alpha(0xFF, 2.0);
        assert_eq!(alpha, 0xFF,
            "opacity > 1.0 should be clamped to 1.0 -> alpha 255");
    }

    #[test]
    fn emit_text_negative_opacity() {
        // Negative opacity: clamp to 0.0
        let alpha = emit_text_compute_alpha(0xFF, -1.0);
        assert_eq!(alpha, 0, "negative opacity must be clamped to 0 -> alpha 0");
    }

    #[test]
    fn emit_text_partial_color_alpha_with_opacity() {
        // Color with alpha=128, opacity=0.5
        // effective = (128/255) * 0.5 = 0.251, byte = 64
        let alpha = emit_text_compute_alpha(128, 0.5);
        assert_eq!(alpha, 64);
    }

    #[test]
    fn emit_text_zero_color_alpha() {
        // Fully transparent color (a=0), opacity=1.0 -> alpha=0
        let alpha = emit_text_compute_alpha(0, 1.0);
        assert_eq!(alpha, 0);
    }

    // ═══════════════════════════════════════════════════════════════════════
    //  8. NEGATIVE LABEL_PADDING GUARD (MARKS/AXIS.RS)
    // ═══════════════════════════════════════════════════════════════════════

    #[test]
    fn label_padding_none_defaults_to_2() {
        assert_eq!(resolve_label_padding(None), 2.0);
    }

    #[test]
    fn label_padding_positive_passes_through() {
        assert_eq!(resolve_label_padding(Some(5.0)), 5.0);
    }

    #[test]
    fn label_padding_zero_passes_through() {
        assert_eq!(resolve_label_padding(Some(0.0)), 0.0);
    }

    #[test]
    fn label_padding_negative_clamped_to_zero() {
        // FIXED: negative label_padding is clamped to 0.0
        assert_eq!(
            resolve_label_padding(Some(-10.0)),
            0.0,
            "FIXED: negative label_padding must be clamped to 0.0"
        );
    }

    #[test]
    fn label_padding_nan_not_clamped() {
        // NaN.max(0.0): in Rust, NaN.max(0.0) returns 0.0 (NaN is unordered,
        // max returns the non-NaN argument).
        let result = resolve_label_padding(Some(f64::NAN));
        assert_eq!(result, 0.0,
            "NaN label_padding.max(0.0) returns 0.0 via IEEE semantics");
    }

    #[test]
    fn label_padding_infinity_passes_through() {
        // Infinity.max(0.0) = Infinity — no guard against huge padding.
        let result = resolve_label_padding(Some(f64::INFINITY));
        assert!(result.is_infinite(),
            "Infinity label_padding is not guarded — passes through");
    }

