    // ═══════════════════════════════════════════════════════════════════════
    //  10. BREAK AXIS REMAP THROUGH BROKEN SCALE
    // ═══════════════════════════════════════════════════════════════════════

    #[test]
    fn remap_coord_identity_no_break() {
        // Single segment covering full domain — remap_coord is identity.
        let br = BreakResult {
            segments: vec![ScaleSegment {
                data_lo: 0.0,
                data_hi: 100.0,
                pixel_lo: 50.0,
                pixel_hi: 350.0,
            }],
        };
        let result = remap_coord(200.0, 0.0, 100.0, 50.0, 350.0, &br);
        assert!(result.is_some());
        let px = result.unwrap();
        // 200.0 pixel -> data_val = 0 + (200-50)/300 * 100 = 50.0 -> maps to 200.0
        assert!((px - 200.0).abs() < 1.0, "identity remap expected ~200, got {px}");
    }

    #[test]
    fn remap_coord_in_gap_returns_none() {
        // Two segments with a gap in between.
        let br = BreakResult {
            segments: vec![
                ScaleSegment { data_lo: 0.0, data_hi: 40.0, pixel_lo: 50.0, pixel_hi: 170.0 },
                ScaleSegment { data_lo: 60.0, data_hi: 100.0, pixel_lo: 182.0, pixel_hi: 350.0 },
            ],
        };
        // A pixel that maps to data value 50 (inside the gap [40, 60]).
        // data_val = 0 + (px - 50) / 300 * 100. For data_val=50: px = 50 + 50*3 = 200.
        let result = remap_coord(200.0, 0.0, 100.0, 50.0, 350.0, &br);
        assert!(result.is_none(), "pixel mapping to gap data value must return None");
    }

    #[test]
    fn remap_coord_zero_span_returns_px() {
        // When px_hi - px_lo is near zero, remap returns Some(px) directly.
        let br = BreakResult {
            segments: vec![ScaleSegment {
                data_lo: 0.0, data_hi: 100.0, pixel_lo: 100.0, pixel_hi: 100.0,
            }],
        };
        let result = remap_coord(100.0, 0.0, 100.0, 100.0, 100.0, &br);
        assert!(result.is_some());
        assert!((result.unwrap() - 100.0).abs() < 1e-10);
    }

    #[test]
    fn remap_coord_nan_pixel_returns_none_or_some() {
        // NaN pixel value: data_val = d_lo + (NaN - px_lo)/span * (d_hi - d_lo) = NaN
        // NaN.clamp(lo, hi) returns NaN in Rust.
        // broken_scale_map(NaN, ...) returns None (NaN >= lo is false).
        let br = BreakResult {
            segments: vec![ScaleSegment {
                data_lo: 0.0, data_hi: 100.0, pixel_lo: 50.0, pixel_hi: 350.0,
            }],
        };
        let result = remap_coord(f64::NAN, 0.0, 100.0, 50.0, 350.0, &br);
        assert!(result.is_none(),
            "NaN pixel coordinate should remap to None (hidden via BREAK_HIDDEN)");
    }

