    // ═══════════════════════════════════════════════════════════════════════

    #[test]
    fn remap_node_polyline_not_remapped() {
        // scene_build.rs remap_node has `_ => {}` for Polyline, Polygon, Image, Raw, Arc.
        // This means break axis does NOT remap Polyline coordinates.
        // If a Polyline mark crosses a break gap, its coordinates are unchanged.
        // This is a known limitation.
        let node_type = "Polyline";
        let is_remapped = matches!(
            node_type,
            "Circle" | "Rect" | "Line" | "Path" | "Text" | "Group"
        );
        assert!(!is_remapped,
            "Polyline nodes are NOT remapped through break axis — known limitation");
    }

    #[test]
    fn remap_node_group_recurses_into_children() {
        // Group nodes recurse into their children for remapping.
        let node_type = "Group";
        let is_remapped = matches!(
            node_type,
            "Circle" | "Rect" | "Line" | "Path" | "Text" | "Group"
        );
        assert!(is_remapped, "Group nodes must recurse into children");
    }

