    //  13. STRIP_SVG_WRAPPER EDGE CASES
    // ═══════════════════════════════════════════════════════════════════════

    #[test]
    fn strip_svg_wrapper_svg_with_no_closing_tag() {
        // SVG with opening tag but no </svg>
        let svg = "<svg><circle/>";
        let inner = strip_svg_wrapper(svg);
        // rfind("</svg>") returns None -> close_start = len = 14
        // open_end = 5 (after first >), close_start = 14
        // &s[5..14] = "<circle/>"
        assert_eq!(inner, "<circle/>",
            "SVG with no closing tag should return everything after opening tag");
    }

    #[test]
    fn strip_svg_wrapper_svg_with_no_closing_bracket() {
        // Malformed: opening tag never closes
        let svg = "<svg malformed";
        let inner = strip_svg_wrapper(svg);
        // find('>') returns None -> return s unchanged
        assert_eq!(inner, svg,
            "SVG tag that never closes should return input unchanged");
    }

    #[test]
    fn strip_svg_wrapper_svg_attributes_with_angle_brackets() {
        // SVG with > inside an attribute value (shouldn't happen in valid SVG,
        // but the parser uses simple find('>') which would break).
        // In practice this is unreachable because SVG attributes can't contain
        // unescaped >. But let's pin the behavior.
        let svg = r#"<svg data-x="a>b"><rect/></svg>"#;
        let inner = strip_svg_wrapper(svg);
        // find('>') finds the > inside the attribute value at position 15.
        // This is a known limitation of the simple parser.
        // open_end = 16, rfind("</svg>") = 24
        // inner = &s[16..24] = "b\"><rect/"
        // This is wrong (parsed incorrectly), but it's a known edge case.
        assert!(!inner.is_empty(),
            "should produce some inner content even if parsed wrong");
    }

