    //  15. INSET BOUNDS EDGE CASES
    // ═══════════════════════════════════════════════════════════════════════

    #[test]
    fn inset_negative_bounds_clamped_to_1px() {
        // bounds where left > right: px_w = (px_right - px_left).max(1.0)
        let b_left = 0.9_f64;
        let b_right = 0.1_f64;
        let plot_w = 300.0_f64;
        let plot_x = 50.0_f64;
        let px_left = plot_x + b_left * plot_w; // 320
        let px_right = plot_x + b_right * plot_w; // 80
        let px_w = (px_right - px_left).max(1.0); // (-240).max(1.0) = 1.0
        assert_eq!(px_w, 1.0,
            "inverted bounds produce 1px clamped width");
    }

    #[test]
    fn inset_nan_bounds_produce_nan_pixel_coords() {
        // NaN in bounds[0] produces NaN px_left. NaN.max(1.0) = 1.0.
        // Actually: f64::NAN comparisons: (NaN - NaN).max(1.0)
        // NaN - NaN = NaN, NaN.max(1.0) = 1.0 (NaN is "less than" in max).
        let b_left = f64::NAN;
        let px_left = 50.0 + b_left * 300.0; // NaN
        assert!(px_left.is_nan(), "NaN bound produces NaN pixel coordinate");
        let px_right = 50.0 + 0.5 * 300.0; // 200.0
        let diff = px_right - px_left; // NaN
        let px_w = diff.max(1.0); // 1.0 (NaN.max returns other)
        assert_eq!(px_w, 1.0,
            "NaN diff.max(1.0) produces 1.0 — inset is 1px wide at NaN position");
    }

