    //  16. BROKEN SCALE MAP EDGE CASES
    // ═══════════════════════════════════════════════════════════════════════

    #[test]
    fn broken_scale_map_degenerate_segment() {
        // A segment where data_lo == data_hi (point domain).
        // The code uses t = 0.5 when data_hi == data_lo.
        let br = BreakResult {
            segments: vec![ScaleSegment {
                data_lo: 50.0,
                data_hi: 50.0,
                pixel_lo: 100.0,
                pixel_hi: 200.0,
            }],
        };
        let result = broken_scale_map(50.0, &br);
        assert!(result.is_some());
        // t = 0.5, pixel = 100 + 0.5 * (200 - 100) = 150
        assert!((result.unwrap() - 150.0).abs() < 1e-10,
            "degenerate segment (lo==hi) maps to pixel midpoint");
    }

    #[test]
    fn broken_scale_map_inverted_segment_data() {
        // data_lo > data_hi (inverted Y axis convention).
        let br = BreakResult {
            segments: vec![ScaleSegment {
                data_lo: 100.0,
                data_hi: 0.0,
                pixel_lo: 50.0,
                pixel_hi: 350.0,
            }],
        };
        // value 50: lo=min(100,0)=0, hi=max(100,0)=100. 50 is in [0, 100].
        // t = (50 - 100) / (0 - 100) = -50 / -100 = 0.5
        // pixel = 50 + 0.5 * (350 - 50) = 200
        let result = broken_scale_map(50.0, &br);
        assert!(result.is_some());
        assert!((result.unwrap() - 200.0).abs() < 1e-10,
            "inverted data segment should map value 50 to pixel midpoint 200");
    }

    #[test]
    fn broken_scale_map_value_at_exact_boundary() {
        // Value exactly at the boundary between two segments.
        let br = BreakResult {
            segments: vec![
                ScaleSegment { data_lo: 0.0, data_hi: 40.0, pixel_lo: 0.0, pixel_hi: 100.0 },
                ScaleSegment { data_lo: 60.0, data_hi: 100.0, pixel_lo: 120.0, pixel_hi: 220.0 },
            ],
        };
        // Value 40 should be in first segment (data_hi = 40, value <= hi).
        let r40 = broken_scale_map(40.0, &br);
        assert!(r40.is_some(), "value at segment boundary should be mapped");
        assert!((r40.unwrap() - 100.0).abs() < 1e-10,
            "value 40 should map to pixel_hi of first segment");

        // Value 60 should be in second segment.
        let r60 = broken_scale_map(60.0, &br);
        assert!(r60.is_some());
        assert!((r60.unwrap() - 120.0).abs() < 1e-10,
            "value 60 should map to pixel_lo of second segment");
    }

