    //  20. ANNOTATION RECT — fill_opacity PROPAGATION
    // ═══════════════════════════════════════════════════════════════════════

    #[test]
    fn annotation_rect_opacity_as_fill_opacity_not_opacity() {
        // In annotation.rs AnnotationSpec::Rect handler, the caller-supplied
        // opacity is stored in fill_opacity, not opacity.
        // opacity is set to 1.0 (not forwarded to SVG).
        // This is critical: to_svg_fill_stroke_with_anchor emits fill_opacity
        // but ignores the opacity field for SVG attributes.
        let caller_opacity = 0.3_f64;
        // Post-fix:
        let fs_opacity = 1.0_f64;
        let fs_fill_opacity = caller_opacity;
        assert!((fs_opacity - 1.0).abs() < f64::EPSILON);
        assert!((fs_fill_opacity - 0.3).abs() < f64::EPSILON);
    }

