    //  23. ANNOTATION ARROW — NaN COORDINATES
    // ═══════════════════════════════════════════════════════════════════════

    #[test]
    fn arrow_nan_start_skips_arrowhead() {
        // If x1 or y1 is NaN, dx = x2 - NaN = NaN, len = NaN.sqrt() = NaN.
        // len > 0.0 is false for NaN, so arrowhead is NOT drawn.
        let x1 = f64::NAN;
        let x2 = 200.0_f64;
        let dx = x2 - x1;
        let dy = 0.0_f64;
        let len = (dx * dx + dy * dy).sqrt();
        assert!(!(len > 0.0), "NaN len skips arrowhead branch");
    }

    #[test]
    fn arrow_coincident_endpoints_no_arrowhead() {
        // x1==x2 && y1==y2: len=0, len > 0.0 is false, no arrowhead.
        let len = 0.0_f64;
        assert!(!(len > 0.0), "zero-length arrow skips arrowhead");
    }

    // ═══════════════════════════════════════════════════════════════════════
    //  24. CONNECTOR CORNER SORTING WITH NaN COORDS
    // ═══════════════════════════════════════════════════════════════════════

    #[test]
    fn connector_nan_connect_to_sort_uses_equal_fallback() {
        // In inset.rs, connector sorting uses .partial_cmp().unwrap_or(Equal).
        // If connect_to is NaN, all distances are NaN.
        // NaN.partial_cmp(NaN) = None -> Equal. All corners tied.
        let cx = f64::NAN;
        let cy = f64::NAN;
        let corner = (100.0_f64, 200.0_f64);
        let d = (corner.0 - cx).hypot(corner.1 - cy);
        assert!(d.is_nan(), "NaN connect_to produces NaN distance");
        let cmp = d.partial_cmp(&d);
        assert!(cmp.is_none(), "NaN partial_cmp returns None");
        // unwrap_or(Equal) means all corners are considered equal distance.
    }

    // ═══════════════════════════════════════════════════════════════════════
    //  25. LEGEND COLOR CONFIG APPLICATION
    // ═══════════════════════════════════════════════════════════════════════

    // In scene_build.rs::build_legend_decorations, chart_config.color is applied
    // to the legend's color_scale via apply_color_config_to_color_scale.
    // This must happen AFTER scale resolution for both panels AND legend.

    #[test]
    fn legend_color_config_applied_after_resolution() {
        // Contract pin: the legend gets chart_config.color applied.
        // Previously it was only applied to panel color scales, not the legend.
        let config_has_color = true;
        let legend_gets_color_config = true;
        assert!(config_has_color && legend_gets_color_config,
            "legend must receive chart_config.color override after scale resolution");
    }

    // ═══════════════════════════════════════════════════════════════════════
    //  26. ANNOTATION IMAGE XML INJECTION
    // ═══════════════════════════════════════════════════════════════════════

    #[test]
    fn annotation_image_src_prevents_xss() {
        let src = r#"evil.png" onload="alert(1)"#;
        let escaped = escape_attr(src);
        let _svg_fragment = format!(r#"<image href="{}"/>"#, escaped);
        // The XSS is neutralized: double quotes are escaped so the browser
        // cannot break out of the href attribute. The literal text "onload="
        // still appears but is inside the attribute value, not as a separate
        // attribute. Verify the quotes are escaped.
        assert!(escaped.contains("&quot;"),
            "double quotes in src must be escaped to &quot;");
        // Verify the escaped string has no raw double quotes that could break
        // out of the attribute.
        assert!(!escaped.contains('"'),
            "escaped src must not contain raw double quotes");
    }

    #[test]
    fn annotation_image_src_ampersand_in_url() {
        let src = "https://example.com/img?a=1&b=2";
        let escaped = escape_attr(src);
        assert!(escaped.contains("&amp;"),
            "ampersand in URL must be escaped to &amp;");
    }

    // ═══════════════════════════════════════════════════════════════════════
    //  27. FMT_F PRECISION CONTRACT
    // ═══════════════════════════════════════════════════════════════════════

    #[test]
    fn fmt_f_precision_is_3_digits() {
        // FLOAT_PRECISION = 3, so format!("{:.3}", x) is used.
        assert_eq!(fmt_f(1.2345), "1.234",
            "precision 3 truncates to 3 decimal places (banker's rounding may apply)");
    }

    #[test]
    fn fmt_f_trailing_zeros_trimmed() {
        assert_eq!(fmt_f(1.0), "1");
        assert_eq!(fmt_f(1.5), "1.5");
        assert_eq!(fmt_f(1.50), "1.5");
    }

    #[test]
    fn fmt_f_very_precise_positive() {
        // 0.001 at precision 3: "0.001" — no trimming needed.
        assert_eq!(fmt_f(0.001), "0.001");
    }

    #[test]
    fn fmt_f_value_rounds_to_zero_after_trimming() {
        // 0.0001 at precision 3: format!("{:.3}", 0.0001) = "0.000"
        // Trim trailing zeros: "0." -> trim dot: "0" -> not empty -> return "0".
        // Wait: trim_end_matches('0') on "0.000" produces "0."
        // Then trim_end_matches('.') produces "0".
        // trimmed = "0", which is not empty, not "-", not "-0".
        assert_eq!(fmt_f(0.0001), "0");
    }

