    //  29. GRIDLINE NODE TYPE DISPATCH
    // ═══════════════════════════════════════════════════════════════════════

    #[test]
    fn gridline_band_rect_falls_through_to_emit_node() {
        // When grid has band_colors, the grid vec contains Rect nodes.
        // emit_gridline_node checks `if let SceneNode::Line { .. } = node`.
        // Rect nodes don't match — they fall through to `emit_node`.
        // This is correct behavior: Rect band fills are emitted as regular nodes.
        let is_line = false;
        let would_call_emit_node = !is_line;
        assert!(would_call_emit_node,
            "grid Rect (band fill) must fall through to emit_node");
    }

    // ═══════════════════════════════════════════════════════════════════════
    //  30. CHART_CONFIG INSET CONNECT_TO RESOLVED THROUGH SCALES
    // ═══════════════════════════════════════════════════════════════════════

    #[test]
    fn inset_connect_to_data_space_resolved_to_pixels() {
        // In scene_build.rs, connect_to [dx, dy] is resolved through primary
        // scales before passing to build_inset_nodes. If the scale's to_pixel_f64
        // returns None, a linear interpolation fallback is used.
        // Pin the contract: the fallback uses data_domain() fractions.
        let d_lo = 0.0_f64;
        let d_hi = 100.0_f64;
        let plot_x = 50.0_f64;
        let plot_w = 300.0_f64;
        let dx = 50.0_f64; // data-space value
        let frac = (dx - d_lo) / (d_hi - d_lo);
        let px_x = plot_x + frac * plot_w;
        assert!((px_x - 200.0).abs() < 1e-10,
            "data value 50 in [0,100] maps to pixel 200 in [50,350]");
    }

    // ═══════════════════════════════════════════════════════════════════════
    //  31. ZOOM TICK LEVELS BREAKPOINTS
    // ═══════════════════════════════════════════════════════════════════════

    #[test]
    fn zoom_breakpoints_cover_full_range() {
        // ZOOM_BREAKPOINTS: [(0.0, 0.5, 4), (0.5, 2.0, 8), (2.0, 4.0, 16), (4.0, 1e9, 32)]
        // min_zoom of first = 0.0, max_zoom of last = 1e9.
        // There should be 4 levels total.
        let breakpoints: &[(f64, f64, usize)] = &[
            (0.0, 0.5, 4),
            (0.5, 2.0, 8),
            (2.0, 4.0, 16),
            (4.0, 1e9, 32),
        ];
        assert_eq!(breakpoints.len(), 4);
        // Verify contiguous coverage: each max_zoom == next min_zoom
        for i in 0..breakpoints.len() - 1 {
            assert!((breakpoints[i].1 - breakpoints[i + 1].0).abs() < 1e-10,
                "zoom breakpoints must be contiguous at index {i}");
        }
        // First starts at 0
        assert_eq!(breakpoints[0].0, 0.0);
        // Last goes to 1e9
        assert_eq!(breakpoints[3].1, 1e9);
    }

    // ═══════════════════════════════════════════════════════════════════════
    //  32. ANNOTATION CALLOUT CHAR WIDTH ESTIMATION
    // ═══════════════════════════════════════════════════════════════════════

    #[test]
    fn callout_char_width_uses_char_count_not_byte_count() {
        let text = "\u{00e9}\u{00e9}\u{00e9}"; // 3 chars, 6 bytes (UTF-8)
        let char_width = 7.0_f64;
        let padding = 4.0_f64;
        let text_w = text.chars().count() as f64 * char_width + padding * 2.0;
        assert_eq!(text_w, 3.0 * 7.0 + 8.0, "width uses char count (3), not byte count (6)");
        let byte_based_w = text.len() as f64 * char_width + padding * 2.0;
        assert!(byte_based_w > text_w,
            "byte-based width would be larger — this is the fixed behavior");
    }

    // ═══════════════════════════════════════════════════════════════════════
    //  33. SECONDARY AXIS DEGENERATE DOMAIN
    // ═══════════════════════════════════════════════════════════════════════

    #[test]
    fn secondary_y_constant_field_expanded() {
        // When all values in the secondary field are identical,
        // the domain is expanded by +-0.5 to avoid a zero-length scale.
        let mn = 42.0_f64;
        let mx = 42.0_f64;
        let (expanded_mn, expanded_mx) = if mn == mx {
            (mn - 0.5, mx + 0.5)
        } else {
            (mn, mx)
        };
        assert_eq!(expanded_mn, 41.5);
        assert_eq!(expanded_mx, 42.5);
    }

    #[test]
    fn secondary_y_nan_min_max_fallback() {
        // If finite_min_max_f64 returns None (all NaN), fallback is (0.0, 1.0).
        let fallback = (0.0_f64, 1.0_f64);
        assert_eq!(fallback.0, 0.0);
        assert_eq!(fallback.1, 1.0);
    }

    // ═══════════════════════════════════════════════════════════════════════
    //  34. ANNOTATION BRACKET UNKNOWN DIRECTION DEFAULTS TO UP
    // ═══════════════════════════════════════════════════════════════════════

    #[test]
    fn bracket_unknown_direction_defaults_to_up() {
        let direction = "diagonal";
        let tip_length = 6.0_f64;
        let (tip_dx, tip_dy) = match direction {
            "up" => (0.0, -tip_length),
            "down" => (0.0, tip_length),
            "left" => (-tip_length, 0.0),
            "right" => (tip_length, 0.0),
            _ => (0.0, -tip_length), // default: up
        };
        assert_eq!(tip_dx, 0.0);
        assert_eq!(tip_dy, -6.0, "unknown direction defaults to up (negative Y)");
    }

